INSERT INTO mail (id,messageType,stationery,mailTemplateId,sender,receiver,subject,body,has_items,expire_time,deliver_time,money,cod,checked) VALUES (2000000001,0,41,0,3851,564,'Из кузни Оргриммара','Lok''tar, воин! В Оргриммаре куют сталь, что не знает страха. Прими наборы для ковки - по двадцать на каждую ступень. Закали ими латы, кольчугу и щит, как закаляют клинки в Долине Чести. Выйдут - ищи меня у трактирщика. За Орду! - Громдар Чёрный Молот',1,1789714760,1781938700,0,0,0);
