INSERT INTO mail (id,messageType,stationery,mailTemplateId,sender,receiver,subject,body,has_items,expire_time,deliver_time,money,cod,checked) VALUES (2000000002,0,41,0,3851,564,'Шкура зверя','Земля-Мать благоволит тебе. Хорошая шкура - дар зверя, и чтить его надо умело. Прими наборы для выделки - по двадцать на каждую ступень. Укрепи ими кожу и чешую, хоть бы и шкуру дьявозавра. Понадобится - я при трактирщике. Иди с духами. - Хемнак Грубокож',1,1789714760,1781938700,0,0,0);
