INSERT INTO mail (id,messageType,stationery,mailTemplateId,sender,receiver,subject,body,has_items,expire_time,deliver_time,money,cod,checked) VALUES (2000000004,0,41,0,3851,564,'Грань самоцвета','Selama ashal''anore. Камень поёт лишь в умелых руках. Дарю наборы для огранки - по двадцать на каждую ступень. Огранируй кольца, амулеты и подвески, от цитрина до арканового кристалла. Нужно ещё - моя витрина у трактирщика. Сияй ярче Солнечного Колодца. - Аэлинор Самоцвет',1,1789714760,1781938700,0,0,0);
