INSERT INTO mail (id,messageType,stationery,mailTemplateId,sender,receiver,subject,body,has_items,expire_time,deliver_time,money,cod,checked) VALUES (2000000005,0,41,0,3851,564,'С точильного камня','Точи клинок, или клинок затупит тебя. Шлю точильные наборы - по двадцать на каждую ступень. Пройди ими по топору, мечу или булаве, и кромка станет злее тролльего клыка. Сточатся - я у трактирщика. Кровь и честь! - Каргал Острокром',1,1789714760,1781938700,0,0,0);
