INSERT INTO mail (id,messageType,stationery,mailTemplateId,sender,receiver,subject,body,has_items,expire_time,deliver_time,money,cod,checked) VALUES (2000000006,0,41,0,3851,564,'Шёпот вуду','Слушай духов, мон. Дерево - ничто, руна - всё. Прими наборы чар - по двадцать на каждую ступень. Влей ими в посох да жезл тайную мощь, что течёт от Зул''Гуруба до Награнда. Иссякнут - ищи меня в тенях у трактирщика. Духи с тобой. - Зен''тари Рунопряд',1,1789714760,1781938700,0,0,0);
