INSERT INTO mail (id,messageType,stationery,mailTemplateId,sender,receiver,subject,body,has_items,expire_time,deliver_time,money,cod,checked) VALUES (2000000014,0,41,0,3851,565,'С доставкой, бабах!','Время - деньги, дружище! Меткость - тоже. Кидаю наборы для оснастки - по двадцать на каждую ступень. Подкрути ими луки, ружья и арбалеты, хоть мифриловым воротом, хоть торием. Запас вышел - стучи через трактирщика. Бабах!.. в смысле, удачи. - Бликс Меднокрут',1,1789714760,1781938700,0,0,0);
