INSERT INTO mail (id,messageType,stationery,mailTemplateId,sender,receiver,subject,body,has_items,expire_time,deliver_time,money,cod,checked) VALUES (2000000017,0,41,0,3851,13853,'Нити Подгорода','Приветствую, дитя Тьмы. Нити помнят холод Подгорода. Высылаю наборы для шитья - по двадцать на каждую ступень. Переплети ими одеяния, от льняного до рунического, и они впитают больше силы. За новыми - к трактирщику. Тьма хранит. - Морвена Хладонить',1,1789714760,1781938700,0,0,0);
